// Applied to every response generated by the Worker (pages, errors, server functions).
// Static files served directly from the assets binding are not covered by this module.

// Production architecture: the browser talks only to same-origin server functions. The one
// external origin is Cloudflare Turnstile (script, widget iframe and its API calls). Add other
// origins only when a feature needs them, e.g. the Supabase project URL if browser SDK access
// is adopted. Supabase, Resend and the health endpoint are server-to-server and need no entry.
export const TURNSTILE_ORIGIN = "https://challenges.cloudflare.com";

export const CONTENT_SECURITY_POLICY = [
  "default-src 'self'",
  // Inline scripts are required by the server-rendered hydration payload and the theme bootstrap.
  // Replace with nonces or hashes when the build supports them (tracked in the launch report).
  `script-src 'self' 'unsafe-inline' ${TURNSTILE_ORIGIN}`,
  "style-src 'self' 'unsafe-inline'",
  "img-src 'self' data: blob:",
  "font-src 'self' data:",
  `connect-src 'self' ${TURNSTILE_ORIGIN}`,
  `frame-src ${TURNSTILE_ORIGIN}`,
  "object-src 'none'",
  "base-uri 'self'",
  "form-action 'self'",
  "frame-ancestors 'none'",
].join("; ");

export const SECURITY_HEADERS: Readonly<Record<string, string>> = {
  "Content-Security-Policy": CONTENT_SECURITY_POLICY,
  "Strict-Transport-Security": "max-age=31536000",
  "X-Content-Type-Options": "nosniff",
  "X-Frame-Options": "DENY",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "Permissions-Policy": "camera=(), microphone=(), geolocation=(), payment=(), usb=()",
  "Cross-Origin-Opener-Policy": "same-origin",
};

/** Returns a copy of the response with security headers added (existing values are kept). */
export function withSecurityHeaders(response: Response): Response {
  const headers = new Headers(response.headers);
  for (const [name, value] of Object.entries(SECURITY_HEADERS)) {
    if (!headers.has(name)) headers.set(name, value);
  }
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}
